using System;using System.IO;using System.Runtime.InteropServices;using SolidWorks.Interop.sldworks;
public static class SWThreadEdges{public static void Run(string root,string mode){var app=(ISldWorks)Marshal.GetActiveObject("SldWorks.Application");var draw=(ModelDoc2)app.ActiveDoc;int e=0,w=0;var m=app.OpenDoc6(Path.Combine(root,"16_Корпус_для_чертежа_v3.SLDPRT"),1,1,"",ref e,ref w);app.ActivateDoc3(m.GetTitle(),false,0,ref e);var prev=(Feature)((PartDoc)m).FeatureByName("Условное изображение резьбы1");if(prev!=null){m.ClearSelection2(true);prev.Select2(false,0);m.EditDelete();}int n=0;var bs=(object[])((PartDoc)m).GetBodies2(0,false);foreach(Body2 b in bs)foreach(Edge ed in (object[])b.GetEdges()){var c=(Curve)ed.GetCurve();if(!c.IsCircle())continue;var a=(double[])c.CircleParams;if(Math.Abs(a[6]-.0017)>1e-8||Math.Abs(a[0]-.017)>1e-8)continue;Console.WriteLine("RIM "+string.Join(";",a));m.ClearSelection2(true);((Entity)ed).Select4(false,null);var f=m.FeatureManager.InsertCosmeticThread2(2,.004,.0025,"M4-6H");if(f==null)throw new Exception("Thread feature");n++;}Console.WriteLine("THREADS "+n);if(n!=4)throw new Exception("Expected four threads");m.ClearSelection2(true);m.EditRebuild3();m.Save3(1,ref e,ref w);app.ActivateDoc3(draw.GetTitle(),false,0,ref e);draw.EditRebuild3();draw.Save3(1,ref e,ref w);}}

